BEGIN;
CREATE TABLE IF NOT EXISTS validation.warehouse_readiness_runs (warehouse_readiness_run_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, analytics_build_run_id bigint NOT NULL REFERENCES analytics.build_runs(analytics_build_run_id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'running' CHECK (status IN ('running','succeeded','failed')), expected_check_count integer NOT NULL CHECK (expected_check_count > 0), completed_check_count integer NOT NULL DEFAULT 0 CHECK (completed_check_count >= 0), passed_check_count integer NOT NULL DEFAULT 0 CHECK (passed_check_count >= 0), failed_check_count integer NOT NULL DEFAULT 0 CHECK (failed_check_count >= 0), total_violations bigint NOT NULL DEFAULT 0 CHECK (total_violations >= 0), started_at timestamptz NOT NULL DEFAULT clock_timestamp(), completed_at timestamptz, error_message text);
CREATE UNIQUE INDEX IF NOT EXISTS uq_warehouse_readiness_runs_successful_build ON validation.warehouse_readiness_runs(analytics_build_run_id) WHERE status = 'succeeded';
CREATE INDEX IF NOT EXISTS ix_warehouse_readiness_runs_status ON validation.warehouse_readiness_runs(status);
CREATE TABLE IF NOT EXISTS validation.warehouse_readiness_results (warehouse_readiness_result_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, warehouse_readiness_run_id bigint NOT NULL REFERENCES validation.warehouse_readiness_runs(warehouse_readiness_run_id) ON DELETE RESTRICT, check_category text NOT NULL, check_name text NOT NULL, passed boolean NOT NULL, violation_count bigint NOT NULL CHECK (violation_count >= 0), check_detail text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE (warehouse_readiness_run_id, check_name), CHECK ((passed AND violation_count = 0) OR (NOT passed AND violation_count > 0)));
COMMENT ON TABLE validation.warehouse_readiness_runs IS 'Persisted Phase 3 Step 7 production-readiness validation runs keyed to an analytics build.';
COMMENT ON TABLE validation.warehouse_readiness_results IS 'Persisted production-readiness checks covering performance hardening, consumer access and warehouse metadata.';
CREATE OR REPLACE FUNCTION validation.validate_warehouse_readiness(p_analytics_build_run_id bigint)
RETURNS TABLE (result_warehouse_readiness_run_id bigint, result_status text, result_already_validated boolean, result_expected_check_count integer, result_completed_check_count integer, result_passed_check_count integer, result_failed_check_count integer, result_total_violations bigint, result_error_message text)
LANGUAGE plpgsql
AS $function$
DECLARE
    v_existing_run_id bigint;
    v_run_id bigint;
    v_expected constant integer := 15;
    v_completed integer := 0;
    v_passed integer := 0;
    v_failed integer := 0;
    v_violations bigint := 0;
BEGIN
    SELECT warehouse_readiness_run_id INTO v_existing_run_id FROM validation.warehouse_readiness_runs WHERE analytics_build_run_id = p_analytics_build_run_id AND status = 'succeeded' ORDER BY warehouse_readiness_run_id LIMIT 1;
    IF v_existing_run_id IS NOT NULL THEN RETURN QUERY SELECT r.warehouse_readiness_run_id, r.status, true, r.expected_check_count, r.completed_check_count, r.passed_check_count, r.failed_check_count, r.total_violations, r.error_message FROM validation.warehouse_readiness_runs r WHERE r.warehouse_readiness_run_id = v_existing_run_id; RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM analytics.build_runs b WHERE b.analytics_build_run_id = p_analytics_build_run_id AND b.status = 'succeeded') THEN RAISE EXCEPTION 'Analytics build % is not succeeded', p_analytics_build_run_id; END IF;
    INSERT INTO validation.warehouse_readiness_runs (analytics_build_run_id, status, expected_check_count) VALUES (p_analytics_build_run_id, 'running', v_expected) RETURNING warehouse_readiness_run_id INTO v_run_id;
    INSERT INTO validation.warehouse_readiness_results (warehouse_readiness_run_id, check_category, check_name, passed, violation_count, check_detail)
    SELECT v_run_id, q.check_category, q.check_name, q.passed, CASE WHEN q.passed THEN 0 ELSE 1 END, q.check_detail
    FROM (
        SELECT 'prerequisite'::text AS check_category, 'reporting_validation_succeeded'::text AS check_name, EXISTS (SELECT 1 FROM validation.reporting_validation_runs r WHERE r.analytics_build_run_id = p_analytics_build_run_id AND r.status = 'succeeded' AND r.expected_check_count = 31 AND r.completed_check_count = 31 AND r.failed_check_count = 0 AND r.total_violations = 0) AS passed, 'Step 6 reporting validation must remain 31/31 with zero violations.'::text AS check_detail
        UNION ALL SELECT 'performance', 'daily_reporting_index_present', to_regclass('analytics.ix_fact_product_event_daily_reporting') IS NOT NULL, 'Daily product KPI covering index must exist.'
        UNION ALL SELECT 'performance', 'feature_reporting_index_present', to_regclass('analytics.ix_fact_product_event_feature_reporting') IS NOT NULL, 'Feature engagement partial covering index must exist.'
        UNION ALL SELECT 'performance', 'observation_time_index_present', to_regclass('analytics.ix_fact_product_event_time') IS NOT NULL, 'Observation cutoff supporting time index must exist.'
        UNION ALL SELECT 'performance', 'observation_cutoff_exact', (SELECT COUNT(*) = 1 AND bool_and(c.observation_cutoff_at = (SELECT MAX(e.occurred_at) FROM analytics.fact_product_event e WHERE e.ingestion_batch_id = c.ingestion_batch_id AND e.analytics_build_run_id = c.analytics_build_run_id)) FROM reporting.vw_observation_cutoff c WHERE c.analytics_build_run_id = p_analytics_build_run_id), 'Reporting cutoff must exactly equal the product-event maximum timestamp.'
        UNION ALL SELECT 'security', 'reader_role_present', EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname = 'pulse_reporting_reader'), 'Read-only reporting group role must exist.'
        UNION ALL SELECT 'security', 'reader_role_hardened', EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname = 'pulse_reporting_reader' AND NOT r.rolcanlogin AND NOT r.rolsuper AND r.rolinherit AND NOT r.rolcreaterole AND NOT r.rolcreatedb AND NOT r.rolreplication AND NOT r.rolbypassrls), 'Reader role must remain NOLOGIN and non-administrative.'
        UNION ALL SELECT 'access', 'reporting_schema_read_only', has_schema_privilege('pulse_reporting_reader', 'reporting', 'USAGE') AND NOT has_schema_privilege('pulse_reporting_reader', 'reporting', 'CREATE'), 'Reader must have reporting USAGE but not CREATE.'
        UNION ALL SELECT 'access', 'reporting_select_complete', (SELECT COUNT(*) > 0 AND bool_and(has_table_privilege('pulse_reporting_reader', c.oid, 'SELECT')) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'reporting' AND c.relkind IN ('r','p','v','m')), 'Reader must be able to SELECT every current reporting relation.'
        UNION ALL SELECT 'access', 'reporting_write_denied', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'reporting' AND c.relkind IN ('r','p','v','m') AND (has_table_privilege('pulse_reporting_reader', c.oid, 'INSERT') OR has_table_privilege('pulse_reporting_reader', c.oid, 'UPDATE') OR has_table_privilege('pulse_reporting_reader', c.oid, 'DELETE') OR has_table_privilege('pulse_reporting_reader', c.oid, 'TRUNCATE'))), 'Reader must have no reporting write privileges.'
        UNION ALL SELECT 'access', 'internal_schema_usage_denied', NOT has_schema_privilege('pulse_reporting_reader', 'raw', 'USAGE') AND NOT has_schema_privilege('pulse_reporting_reader', 'staging', 'USAGE') AND NOT has_schema_privilege('pulse_reporting_reader', 'validation', 'USAGE') AND NOT has_schema_privilege('pulse_reporting_reader', 'analytics', 'USAGE'), 'Reader must not have USAGE on internal schemas.'
        UNION ALL SELECT 'access', 'internal_select_denied', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname IN ('raw','staging','validation','analytics') AND c.relkind IN ('r','p','v','m') AND has_table_privilege('pulse_reporting_reader', c.oid, 'SELECT')), 'Reader must not have direct SELECT privileges on internal relations.'
        UNION ALL SELECT 'access', 'default_reporting_select_present', EXISTS (SELECT 1 FROM pg_default_acl d JOIN pg_namespace n ON n.oid = d.defaclnamespace JOIN pg_roles owner_role ON owner_role.oid = d.defaclrole CROSS JOIN LATERAL aclexplode(d.defaclacl) a JOIN pg_roles grantee_role ON grantee_role.oid = a.grantee WHERE owner_role.rolname = 'pulse_app' AND n.nspname = 'reporting' AND d.defaclobjtype = 'r' AND grantee_role.rolname = 'pulse_reporting_reader' AND a.privilege_type = 'SELECT'), 'Future pulse_app reporting relations must inherit reader SELECT.'
        UNION ALL SELECT 'metadata', 'analytics_object_comments_complete', (SELECT COUNT(*) > 0 AND COUNT(*) = COUNT(obj_description(c.oid, 'pg_class')) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'analytics' AND c.relkind IN ('r','p','v','m')), 'Every analytics table/view must have an object comment.'
        UNION ALL SELECT 'metadata', 'reporting_object_comments_complete', (SELECT COUNT(*) > 0 AND COUNT(*) = COUNT(obj_description(c.oid, 'pg_class')) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'reporting' AND c.relkind IN ('r','p','v','m')), 'Every reporting table/view must have an object comment.'
    ) q;
    SELECT COUNT(*), COUNT(*) FILTER (WHERE passed), COUNT(*) FILTER (WHERE NOT passed), COALESCE(SUM(violation_count),0) INTO v_completed, v_passed, v_failed, v_violations FROM validation.warehouse_readiness_results WHERE warehouse_readiness_run_id = v_run_id;
    UPDATE validation.warehouse_readiness_runs SET status = CASE WHEN v_failed = 0 AND v_completed = v_expected THEN 'succeeded' ELSE 'failed' END, completed_check_count = v_completed, passed_check_count = v_passed, failed_check_count = v_failed, total_violations = v_violations, completed_at = clock_timestamp() WHERE warehouse_readiness_run_id = v_run_id;
    RETURN QUERY SELECT r.warehouse_readiness_run_id, r.status, false, r.expected_check_count, r.completed_check_count, r.passed_check_count, r.failed_check_count, r.total_violations, r.error_message FROM validation.warehouse_readiness_runs r WHERE r.warehouse_readiness_run_id = v_run_id;
EXCEPTION WHEN OTHERS THEN
    IF v_run_id IS NOT NULL THEN UPDATE validation.warehouse_readiness_runs SET status = 'failed', completed_at = clock_timestamp(), error_message = SQLERRM WHERE warehouse_readiness_run_id = v_run_id; RETURN QUERY SELECT r.warehouse_readiness_run_id, r.status, false, r.expected_check_count, r.completed_check_count, r.passed_check_count, r.failed_check_count, r.total_violations, r.error_message FROM validation.warehouse_readiness_runs r WHERE r.warehouse_readiness_run_id = v_run_id; RETURN; END IF;
    RAISE;
END;
$function$;
COMMENT ON FUNCTION validation.validate_warehouse_readiness(bigint) IS 'Runs and persists 15 Phase 3 Step 7 warehouse production-readiness checks. Successful validation is idempotent per analytics build.';
COMMIT;
